        ["Your in-game graphics settings may reset once. Setup keeps a copy and puts it back if you switch back."] =
            "Grafická nastavení ve hře se mohou jednou resetovat. Instalátor uchová kopii a vrátí ji, pokud přepnete zpět.",
        ["Fixes for game and graphics settings."] = "Opravy nastavení hry a grafiky.",
        ["Fixes stutters, Sims getting stuck and crashes."] = "Opravuje trhání, zaseknuté Simíky a pády.",
        ["Needed only by some script mods; turn it on if a mod asks for it."] =
            "Potřebují ho jen některé skriptové mody; zapněte ho, pokud ho mod vyžaduje.",
        ["Makes the game run faster. Needs a free Nexus Mods account; Setup installs it when your download finishes."] =
            "Hra poběží rychleji. Vyžaduje bezplatný účet na Nexus Mods; instalátor ho nainstaluje, až se stahování dokončí.",
        ["Puts back the graphics files you had before."] = "Vrátí grafické soubory, které jste měli dříve.",
        ["Goes back to the game's default graphics. Your in-game graphics settings may reset once."] =
            "Vrátí výchozí grafiku hry. Grafická nastavení ve hře se mohou jednou resetovat.",
        ["Language"] = "Jazyk",
        ["Automatic"] = "Automaticky",
        ["This file has no Sims3Performance.asi."] = "Tento soubor neobsahuje Sims3Performance.asi.",
        ["Dry run: Setup changes nothing."] = "Zkušební běh: instalátor nic nemění.",
        ["Apex Radiance by loinyx. The RTX Remix bridge is NVIDIA's, ported to The Sims 3 by dalexlol and alexvixell35-stack. Sims3SettingsSetter is by sims3fiend, Sims 3 Modernization by rodneypantonial and Ultimate ASI Loader by ThirteenAG: Setup downloads them from their own GitHub releases."] =
            "Apex Radiance od loinyx. RTX Remix bridge je od NVIDIA, pro The Sims 3 ho převedli dalexlol a alexvixell35-stack. Sims3SettingsSetter je od sims3fiend, Sims 3 Modernization od rodneypantonial a Ultimate ASI Loader od ThirteenAG: instalátor je stahuje z jejich vlastních vydání na GitHubu.",
        ["RTX Remix bridge: third-party notices"] = "RTX Remix bridge: oznámení třetích stran",
        ["Read"] = "Číst",
        ["Licence text"] = "Text licence",
        ["OK"] = "OK",
        ["Cancel"] = "Zrušit",
        ["A new Setup is available"] = "Je k dispozici nový Setup",
        ["Apex Radiance Setup {0} was downloaded and checked. Update Setup, then it opens again."] = "Apex Radiance Setup {0} byl stažen a ověřen. Aktualizuj Setup a znovu se otevře.",
        ["Update Setup"] = "Aktualizovat Setup",
        // restart host (experimental)
        ["Restart host"] = "Restart hry",
        ["Experimental"] = "Experimentální",
        ["After a save made low on memory, offers to start the game again into that save when you quit."] = "Když uložíte hru s nedostatkem paměti, nabídne při ukončení spustit hru znovu s touto pozicí.",
        ["Start the game once with Apex Radiance, then turn on the restart host here."] = "Spusťte hru jednou s Apex Radiance a potom zde zapněte restart hry.",
        ["Removes ts3wrap.exe and turns the restart host off in ApexRadiance.toml."] = "Odebere ts3wrap.exe a vypne restart hry v ApexRadiance.toml.",
        ["Your NVIDIA card draws an extra picture between every two the game makes, so the game looks about twice as smooth. Only on RTX 40 and 50 series cards; best with the frame limit at 60 to 90 fps."] = "Vaše karta NVIDIA vykreslí mezi každé dva snímky hry jeden navíc, takže hra vypadá asi dvakrát plynuleji. Jen na kartách RTX řady 40 a 50; nejlépe s limitem snímků 60 až 90 fps.",
        ["On for The Sims 3 in the NVIDIA driver. Works best with Apex's frame limit at 60 to 90 fps."] = "Zapnuto pro The Sims 3 v ovladači NVIDIA. Nejlépe funguje s limitem snímků v Apex na 60 až 90 fps.",
        ["On for The Sims 3 in the NVIDIA driver. Apex's frame limit is now 60 fps, the pace it works best at."] = "Zapnuto pro The Sims 3 v ovladači NVIDIA. Limit snímků v Apex je nyní 60 fps, se kterým funguje nejlépe.",
        ["Off for The Sims 3."] = "Vypnuto pro The Sims 3.",
        ["Already in your NVIDIA profile \"{0}\": Setup leaves it as it is."] = "Už je ve vašem profilu NVIDIA \"{0}\": Setup ho nechá být.",
        ["Needs an NVIDIA GeForce RTX 40 or 50 series card (found: {0})."] = "Vyžaduje kartu NVIDIA GeForce RTX řady 40 nebo 50 (nalezeno: {0}).",
        ["Needs NVIDIA driver 571.86 or newer (found: {0})."] = "Vyžaduje ovladač NVIDIA 571.86 nebo novější (nalezeno: {0}).",
        ["Needs the RTX Remix bridge as the graphics choice."] = "Vyžaduje RTX Remix bridge jako volbu grafiky.",
        ["Could not read the NVIDIA driver settings: {0}"] = "Nastavení ovladače NVIDIA nelze přečíst: {0}",
        ["Could not change the NVIDIA driver settings: {0}"] = "Nastavení ovladače NVIDIA nelze změnit: {0}",
        ["Turn on {0}"] = "Zapnout {0}",
        ["Turn off {0}"] = "Vypnout {0}",
        ["The AMD driver adds frames for smoother motion, about double the frame rate, with a little more input delay. It applies to every game on this PC."] = "Ovladač AMD přidává snímky pro plynulejší pohyb, zhruba dvojnásobná snímková frekvence, s o něco větším zpožděním ovládání. Platí pro všechny hry na tomto PC.",
        ["Not available on this AMD card or driver: AMD Fluid Motion Frames needs a Radeon RX 6000 series card or newer and a recent driver."] = "Na této kartě nebo ovladači AMD není k dispozici: AMD Fluid Motion Frames vyžaduje Radeon RX řady 6000 nebo novější a aktuální ovladač.",
        ["Could not read the AMD driver settings: {0}"] = "Nastavení ovladače AMD nelze přečíst: {0}",
        ["Could not change the AMD driver settings: {0}"] = "Nastavení ovladače AMD nelze změnit: {0}",
        ["On in the AMD driver, for every game. Apex's frame limit is now 60 fps, the pace it works best at."] = "Zapnuto v ovladači AMD, pro všechny hry. Limit snímků Apexu je nyní 60 FPS, tempo, při kterém funguje nejlépe.",
        ["On in the AMD driver, for every game. Works best with Apex's frame limit at 60 to 90 fps."] = "Zapnuto v ovladači AMD, pro všechny hry. Nejlépe funguje s limitem snímků Apexu 60 až 90 FPS.",
        ["Off in the AMD driver."] = "Vypnuto v ovladači AMD.",
        ["Apex frame limit"] = "Limit snímků Apexu",
        ["{0} doubles what you see: a 60 fps limit shows about 120 on screen. Works best at 60 to 90 fps."] = "{0} zdvojnásobí, co vidíte: limit 60 FPS ukáže na obrazovce asi 120. Funguje nejlépe při 60 až 90 FPS.",
        ["Off"] = "Vypnuto",
        ["{0} fps"] = "{0} FPS",
        ["{0} fps (recommended)"] = "{0} FPS (doporučeno)",
        ["Keep: {0}"] = "Ponechat: {0}",
        ["no limit"] = "bez limitu",
        ["Custom"] = "Vlastní",
        ["Could not change Apex's frame limit: {0}"] = "Limit snímků Apexu nelze změnit: {0}",
        ["Turned on outside Setup, in the NVIDIA driver settings: Setup leaves it as it is."] = "Zapnuto mimo Setup, v nastavení ovladače NVIDIA: Setup ho nechá být.",
        ["{0} fps → about {1} fps on screen with {2}"] = "{0} FPS → asi {1} FPS na obrazovce s {2}",
        ["No limit: about double your frame rate on screen with {0}"] = "Bez limitu: zhruba dvojnásobná snímková frekvence na obrazovce s {0}",
        ["Turns on when you apply the changes."] = "Zapne se po použití změn.",
        ["Turns off when you apply the changes."] = "Vypne se po použití změn.",
        ["Changes to {0} when you apply the changes."] = "Změní se na {0} po použití změn.",
        ["Apex frame limit: {0}"] = "Limit snímků Apexu: {0}",
        ["To apply: {0}"] = "K použití: {0}",
        ["Windows did not let Setup change the driver settings. Close the NVIDIA App and NVIDIA Profile Inspector, then try again."] = "Windows nedovolil Setupu změnit nastavení ovladače. Zavřete NVIDIA App a NVIDIA Profile Inspector a zkuste to znovu.",
        ["The AMD driver did not accept the change. You can turn it on by hand in AMD Software: Gaming > Graphics > AMD Fluid Motion Frames."] = "Ovladač AMD změnu nepřijal. Zapnout to můžete ručně v AMD Software: Hry > Grafika > AMD Fluid Motion Frames.",
        ["The NVIDIA driver did not accept the change. You can turn it on by hand with NVIDIA Profile Inspector."] = "Ovladač NVIDIA změnu nepřijal. Zapnout to můžete ručně v NVIDIA Profile Inspector.",
        ["How to do it by hand"] = "Jak to udělat ručně",
        ["GitHub's download limit was reached; try again in {0} minutes."] = "Byl dosažen limit stahování GitHubu; zkuste to znovu za {0} min.",
        ["Your antivirus removed or blocked {0}; add an exception for {1} and run Setup again."] = "Váš antivirus odstranil nebo zablokoval {0}; přidejte výjimku pro {1} a spusťte Setup znovu.",
        ["Close The Sims 3, its launcher, the restart host (ts3wrap.exe) and the RTX Remix bridge (NvRemixBridge.exe), then try again."] = "Zavřete The Sims 3, jeho spouštěč, restart hry (ts3wrap.exe) a RTX Remix bridge (NvRemixBridge.exe) a zkuste to znovu.",
        ["Setup cannot write to {0}. If Windows Security's Controlled folder access is on, allow ApexRadianceSetup.exe there; or move the game out of a protected folder."] = "Setup nemůže zapisovat do {0}. Pokud je v Zabezpečení Windows zapnutý řízený přístup ke složkám, povolte tam ApexRadianceSetup.exe; nebo přesuňte hru z chráněné složky.",
        ["Setup needs {0} MB free on drive {1}. Free some space, then try again."] = "Setup potřebuje {0} MB volného místa na jednotce {1}. Uvolněte místo a zkuste to znovu.",
        ["Setup did not find The Sims 3's folder in Documents. Start the game once, then run Setup again for the settings it writes there."] = "Setup nenašel složku The Sims 3 v Dokumentech. Spusťte hru jednou a pak znovu Setup, kvůli nastavením, která tam zapisuje.",
        ["{0} (d3d9.dll) is set aside in Game\\Bin\\Apex Radiance backup; removing the renderer in Repair or remove puts it back."] = "{0} (d3d9.dll) se odloží do Game\\Bin\\Apex Radiance backup; odebrání rendereru v Opravit nebo odebrat ho vrátí.",
        ["Two ASI loaders ({0}): Setup keeps {1} and sets the others aside in Game\\Bin\\Apex Radiance backup."] = "Dva ASI loadery ({0}): Setup ponechá {1} a ostatní odloží do Game\\Bin\\Apex Radiance backup.",
        ["Before Setup can continue"] = "Než Setup bude moci pokračovat",
        ["Before Setup continues"] = "Než Setup bude pokračovat",
        ["Continue"] = "Pokračovat",
        ["Windows did not let Setup change a file. If Windows Security's Controlled folder access is on, allow ApexRadianceSetup.exe there; a read-only or locked file can also cause this."] = "Windows nedovolil Setupu změnit soubor. Pokud je zapnutý řízený přístup ke složkám, povolte tam ApexRadianceSetup.exe; příčinou může být i soubor jen pro čtení nebo zamčený soubor.",
        ["A file Setup needed is in use or could not be written. Close the game and other programs using it, then try again."] = "Soubor, který Setup potřebuje, se používá nebo ho nešlo zapsat. Zavřete hru a další programy, které ho používají, a zkuste to znovu.",
        ["Setup ran into a problem it did not expect."] = "Setup narazil na neočekávaný problém.",
        ["Copy details"] = "Kopírovat podrobnosti",
        ["Open log folder"] = "Otevřít složku protokolu",
        ["Setup puts back the files it changed."] = "Setup vrátí soubory, které změnil.",
        ["Keep what was installed"] = "Ponechat nainstalované",
        ["Close The Sims 3, its launcher, the restart host (ts3wrap.exe) and the RTX Remix bridge (NvRemixBridge.exe) to continue."] = "Zavřete The Sims 3, jeho spouštěč, restart hry (ts3wrap.exe) a RTX Remix bridge (NvRemixBridge.exe) a pokračujte.",
        ["Close The Sims 3, its launcher, the restart host (ts3wrap.exe) and the RTX Remix bridge (NvRemixBridge.exe) to update."] = "Zavřete The Sims 3, jeho spouštěč, restart hry (ts3wrap.exe) a RTX Remix bridge (NvRemixBridge.exe) a aktualizujte.",
        ["Setup could not find {0}. Download the Sims 3 Performance Patch again, or choose the downloaded file again."] = "Setup nenašel {0}. Stáhněte Sims 3 Performance Patch znovu, nebo znovu vyberte stažený soubor.",
        ["Setup could not put the files back while The Sims 3, its launcher, the restart host or the RTX Remix bridge runs. Close them, then click Restore on the newest point in Repair or remove."] = "Setup nemohl vrátit soubory, dokud běží The Sims 3, jeho spouštěč, restart hry nebo RTX Remix bridge. Zavřete je a pak v Opravit nebo odebrat klikněte na Obnovit u nejnovějšího bodu.",
        ["Frame generation was turned off with the removal and stays off; turn it on again in Components if you want it."] = "Generování snímků se s odebráním vypnulo a zůstává vypnuté; pokud ho chcete, zapněte ho znovu v Součástech.",
        ["Setup could not update itself"] = "Setup se nemohl aktualizovat",
        ["Some changes did not apply"] = "Některé změny se nepoužily",
        ["Not changed: {0}"] = "Nezměněno: {0}",
        ["The AMD driver did not accept the change. You can turn it off by hand in AMD Software: Gaming > Graphics > AMD Fluid Motion Frames."] = "Ovladač AMD změnu nepřijal. Vypnout to můžete ručně v AMD Software: Hry > Grafika > AMD Fluid Motion Frames.",
        ["The NVIDIA driver did not accept the change. You can turn it off by hand with NVIDIA Profile Inspector."] = "Ovladač NVIDIA změnu nepřijal. Vypnout to můžete ručně v NVIDIA Profile Inspector.",
        ["Windows did not let Setup change the driver settings. Close AMD Software, then try again."] = "Windows nedovolil Setupu změnit nastavení ovladače. Zavřete AMD Software a zkuste to znovu.",
        ["The download of {0} was damaged. Try again; if it repeats, an antivirus web shield or a proxy may be changing downloads."] = "Stažený soubor {0} byl poškozený. Zkuste to znovu; pokud se to opakuje, stahování možná mění webový štít antiviru nebo proxy.",
        ["Your antivirus blocked a file Setup needs; add an exception for {0} and run Setup again."] = "Váš antivirus zablokoval soubor, který Setup potřebuje; přidejte výjimku pro {0} a spusťte Setup znovu.",
        ["Faster text lookups is off while {0} is in Mods\\Packages: that package already merges the string tables. To use it, remove {0}."] = "Rychlejší vyhledávání textů je vypnuté, dokud je {0} v Mods\\Packages: ten balíček už tabulky textů slučuje. Chcete-li je použít, odstraňte {0}.",
        ["Faster text lookups is off because {0} ({1}) changes the same code. To use it, set {2} in the [Patches] section of {3}, or remove {1}."] = "Rychlejší vyhledávání textů je vypnuté, protože {0} ({1}) mění stejný kód. Chcete-li je použít, nastavte {2} v sekci [Patches] souboru {3}, nebo odstraňte {1}.",
        ["Faster text lookups was off in the last game because {0} changes the same code. To use it, turn off the part of that mod that changes text lookups, or remove {0}."] = "Rychlejší vyhledávání textů bylo v minulé hře vypnuté, protože {0} mění stejný kód. Chcete-li je použít, vypněte část toho modu, která mění vyhledávání textů, nebo odstraňte {0}.",
    };
}
